# Find blocks of repeated colors
import numpy as np

def find_blocks(grid, color, min_size=2):
    """Find connected blocks of a given color"""
    h, w = len(grid), len(grid[0])
    blocks = []
    visited = set()

    for r in range(h):
        for c in range(w):
            if grid[r][c] == color and (r, c) not in visited:
                block = []
                queue = [(r, c)]
                while queue:
                    cr, cc = queue.pop(0)
                    if (cr, cc) in visited or grid[cr][cc] != color:
                        continue
                    visited.add((cr, cc))
                    block.append((cr, cc))
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < h and 0 <= nc < w:
                            if grid[nr][nc] == color and (nr, nc) not in visited:
                                queue.append((nr, nc))
                if len(block) >= min_size:
                    block_rows = sorted(set(r for r, c in block))
                    block_cols = sorted(set(c for r, c in block))
                    blocks.append((block_rows[0], block_cols[0], color, len(block)))
    return blocks

